get_seo_configuration.code:
const response = await client.seoConfiguration.getSeoConfiguration();
const settings = response.map.seo_configuration;
console.log(settings.global_store_settings.store_name, settings.global_store_settings.title_separator);
console.log(settings.url_settings.regenerate_url_on_item_update, settings.url_settings.auto_redirect_on_url_change);
console.log(settings.document_root.items.length, settings.url_settings.redirects.items.length);

put_seo_configuration.code:
const response = await client.seoConfiguration.putSeoConfiguration({
    seo_configuration: {url_settings: {regenerate_url_on_item_update: true, auto_redirect_on_url_change: true}},
});
const urlSettings = response.map.seo_configuration.url_settings;
console.log(urlSettings.regenerate_url_on_item_update, urlSettings.auto_redirect_on_url_change);

get_seo_configuration_section.code:
const response = await client.seoConfiguration.getSeoConfigurationSection('url_settings');
const urlSettings = response.map.url_settings;
console.log(urlSettings.regenerate_url_on_item_update, urlSettings.auto_redirect_on_url_change);
for (const redirect of urlSettings.redirects.items) {
    console.log(redirect.id, redirect.source_url, redirect.destination_url);
}

