get_seo_configuration_document_root.code:
const response = await client.seoConfiguration.getSeoConfigurationDocumentRoot({limit: 100});
for (const file of response.map.items) {
    console.log(file.config_key, file.file_name, file.file_path);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

upload_seo_configuration_document_root.code:
import {readFileSync} from 'node:fs';

const response = await client.seoConfiguration.uploadSeoConfigurationDocumentRoot({
    file: ['verification.txt', readFileSync('verification.txt'), 'text/plain'],
});
const file = response.map.document_root_file;
console.log(file.config_key, file.file_name, file.file_path);

